import { BasePineconeError } from './base';

/** Details of an unsuccessful HTTP request, used to construct API errors. */
export type FailedRequestInfo = {
  /** HTTP response status code. */
  status: number;
  /** URL of the failed request. */
  url?: string;
  /** Response body returned by the server. */
  body?: string;
  /** Human-readable server error message. */
  message?: string;
};

const CONFIG_HELP = `You can find the configuration values for your project in the Pinecone developer console at https://app.pinecone.io`;

const BILLING_HELP = `You can review your plan and billing details in the Pinecone developer console at https://app.pinecone.io/organizations/-/settings/billing`;

/**
 * Pinecone rejected the request with status 400 or 403.
 * Read the error message to identify invalid input or a restriction on the operation.
 */
export class PineconeBadRequestError extends BasePineconeError {
  constructor(failedRequest: FailedRequestInfo) {
    const { message } = failedRequest;
    super(message);
    this.name = 'PineconeBadRequestError';
  }
}

/**
 * Pinecone rejected the credentials. Check that your API key or service-account
 * credentials are valid and have not been revoked.
 *
 * @see {@link PineconeConfiguration} and {@link AdminClientConfiguration}.
 */
export class PineconeAuthorizationError extends BasePineconeError {
  constructor(failedRequest: FailedRequestInfo, messageOverride?: string) {
    const { url } = failedRequest;
    if (messageOverride) {
      // Allows callers whose credentials are not an Api-Key (e.g. the Admin API's service-account
      // OAuth flow) to supply accurate wording instead of the default Api-Key message.
      super(messageOverride);
    } else if (url) {
      super(
        `The API key you provided was rejected while calling ${url}. Please check your configuration values and try again. ${CONFIG_HELP}`,
      );
    } else {
      super(
        `The API key you provided was rejected. Please check your configuration values and try again. ${CONFIG_HELP}`,
      );
    }
    this.name = 'PineconeAuthorizationError';
  }
}

/**
 * This error is thrown when API requests return with status 402 (Payment
 * Required), signaling a billing problem such as quota exhaustion, a
 * declined card, or a plan limit.
 *
 * Catch this error to surface the billing issue to the user rather than
 * treating it as a generic unmapped error.
 */
export class PineconePaymentRequiredError extends BasePineconeError {
  constructor(failedRequest: FailedRequestInfo) {
    const { url, message } = failedRequest;
    if (url) {
      super(
        `A call to ${url} returned HTTP status 402 (Payment Required). ${message ? message : ''} ${BILLING_HELP}`.trim(),
      );
    } else {
      super(
        `The request could not be completed due to a billing problem with your account. ${message ? message : ''} ${BILLING_HELP}`.trim(),
      );
    }
    this.name = 'PineconePaymentRequiredError';
  }
}

/**
 * This error is thrown when interacting with a resource such as an index or collection
 * that cannot be found.
 */
export class PineconeNotFoundError extends BasePineconeError {
  constructor(failedRequest: FailedRequestInfo) {
    const { url } = failedRequest;
    if (url) {
      super(`A call to ${url} returned HTTP status 404.`);
    } else {
      super('The requested resource could not be found.');
    }

    this.name = 'PineconeNotFoundError';
  }
}

/**
 * This error is thrown when attempting to create a resource such as an index or
 * collection with a name that is already in use.
 * */
export class PineconeConflictError extends BasePineconeError {
  constructor(failedRequest: FailedRequestInfo) {
    const { url, message } = failedRequest;
    if (url) {
      super(
        `A call to ${url} returned HTTP status 409. ${message ? message : ''}`,
      );
    } else {
      super('The resource you are attempting to create already exists.');
    }

    this.name = 'PineconeConflictError';
  }
}

/**
 * This error is thrown when API requests return with status 412
 * (Precondition Failed), meaning a precondition the request depended on -
 * such as an expected resource state or a conditional header - no longer
 * holds. For example, retrying a delete against a namespace that a prior
 * request already deleted.
 */
export class PineconeFailedPreconditionError extends BasePineconeError {
  constructor(failedRequest: FailedRequestInfo) {
    const { url, message } = failedRequest;
    if (url) {
      super(
        `A call to ${url} returned HTTP status 412 (Precondition Failed). ${message ? message : ''}`.trim(),
      );
    } else {
      super(
        `The request could not be completed because a precondition failed. ${message ? message : ''}`.trim(),
      );
    }
    this.name = 'PineconeFailedPreconditionError';
  }
}

/**
 * This error is thrown when API requests return with status 422
 * (Unprocessable Entity). The request was well-formed, but the server was
 * unable to process it because its contents are semantically invalid.
 *
 * A common cause is a request body that does not match the schema expected by
 * the endpoint, such as creating an index with a field configuration that is
 * not permitted.
 */
export class PineconeUnprocessableEntityError extends BasePineconeError {
  constructor(failedRequest: FailedRequestInfo) {
    const { url, message } = failedRequest;
    if (url) {
      super(
        `A call to ${url} returned HTTP status 422 (Unprocessable Entity). ${message ? message : ''}`.trim(),
      );
    } else {
      super(
        `The request could not be processed because its contents are invalid. ${message ? message : ''}`.trim(),
      );
    }
    this.name = 'PineconeUnprocessableEntityError';
  }
}

/**
 * This error indicates API responses are returning with status 500 and
 * something is wrong with Pinecone. Check the [status page](https://status.pinecone.io/)
 * for information about current or recent outages.
 *
 * @see [Pinecone's status page](https://status.pinecone.io/)
 */
export class PineconeInternalServerError extends BasePineconeError {
  constructor(failedRequest: FailedRequestInfo) {
    const { url, body, status } = failedRequest;
    const intro = url
      ? `An internal server error occurred while calling the ${url} endpoint.`
      : '';
    const help = `To see overall service health and learn whether this seems like a large-scale problem or one specific to your request, please go to https://status.pinecone.io/ to view our status page. If you believe the error reflects a problem with this client, please file a bug report in the github issue tracker at https://github.com/pinecone-io/pinecone-ts-client`;
    const statusMessage = status ? `Status Code: ${status}.` : '';
    const bodyMessage = body ? `Body: ${body}` : '';
    super([intro, statusMessage, help, bodyMessage].join(' ').trim());
    this.name = 'PineconeInternalServerError';
  }
}

/* We can choose to throw this error when we want to limit requests to the server. When instantiated, pass the
 number of retries the user has made already. */
/** Raised when a request still fails after all configured retry attempts. */
export class PineconeMaxRetriesExceededError extends BasePineconeError {
  constructor(retries: number) {
    const intro = `You have exceeded the max configured retries (${retries}). `;
    const help =
      'Increase the maxRetries field in the RetryOptions object to retry more times. If you believe the' +
      ' error reflects a problem with this client, please file a bug report in the github issue tracker at https://github.com/pinecone-io/pinecone-ts-client';
    super([intro, help].join(' ').trim());
    this.name = 'PineconeMaxRetriesExceededError';
  }
}

/**
 * Pinecone returned status 503 (Service Unavailable).
 * The service is temporarily unable to handle the request.
 *
 * @see [Pinecone service status](https://status.pinecone.io/)
 */
export class PineconeUnavailableError extends BasePineconeError {
  constructor(failedRequest: FailedRequestInfo) {
    const { url, body, status } = failedRequest;
    const intro = url
      ? `The Pinecone service (${url}) is temporarily unavailable.`
      : '';
    const statusMessage = status ? `Status Code: ${status}.` : '';
    const help = `To see overall service health and learn whether this seems like a large-scale problem or one specific to your request, please go to https://status.pinecone.io/ to view our status page. If you believe the error reflects a problem with this client, please file a bug report in the github issue tracker at https://github.com/pinecone-io/pinecone-ts-client`;
    const bodyMessage = body ? `Body: ${body}` : '';
    super([intro, statusMessage, help, bodyMessage].join(' ').trim());
    this.name = 'PineconeUnavailableError';
  }
}

/**
 * Pinecone returned status 501 (Not Implemented).
 * Read the response message to identify the unsupported operation.
 */
export class PineconeNotImplementedError extends BasePineconeError {
  constructor(requestInfo: FailedRequestInfo) {
    const { url, message } = requestInfo;
    if (url) {
      super(
        `A call to ${url} returned HTTP status 501. ${message ? message : ''}`,
      );
    } else {
      super();
    }
    this.name = 'PineconeNotImplementedError';
  }
}

/**
 * This error is thrown when an API endpoint does not support the HTTP method
 * used in the request. This typically indicates the operation is not available
 * for the targeted resource.
 */
export class PineconeMethodNotAllowedError extends BasePineconeError {
  constructor(failedRequest: FailedRequestInfo) {
    const { url, message } = failedRequest;
    if (url) {
      super(
        `A call to ${url} returned HTTP status 405 (Method Not Allowed). ${message ? message : ''}`.trim(),
      );
    } else {
      super(
        `The HTTP method used is not allowed for this endpoint. ${message ? message : ''}`.trim(),
      );
    }
    this.name = 'PineconeMethodNotAllowedError';
  }
}

/**
 * Thrown when `waitUntilReady: true` is used and the index does not become
 * ready within the specified `timeout`.
 */
export class PineconeTimeoutError extends BasePineconeError {
  constructor(indexName: string, timeoutMs: number) {
    super(
      `Index '${indexName}' was not ready within ${timeoutMs}ms. You can increase the timeout by passing a larger value for the \`timeout\` option.`,
    );
    this.name = 'PineconeTimeoutError';
  }
}

/**
 * Thrown when an index enters the `InitializationFailed` state during
 * `waitUntilReady` polling.
 */
export class PineconeIndexInitializationFailedError extends BasePineconeError {
  constructor(indexName: string) {
    super(
      `Index '${indexName}' failed to initialize. Check the Pinecone console for more details.`,
    );
    this.name = 'PineconeIndexInitializationFailedError';
  }
}

/**
 * Thrown when an index enters a terminal non-ready state (`Terminating` or
 * `Disabled`) during `waitUntilReady` polling.
 */
export class PineconeIndexTerminatedError extends BasePineconeError {
  constructor(indexName: string, state: string) {
    super(
      `Index '${indexName}' entered '${state}' state and will not become ready.`,
    );
    this.name = 'PineconeIndexTerminatedError';
  }
}

/**
 * This catch-all exception is thrown when a request error that is not
 * specifically mapped to another exception is thrown.
 */
export class PineconeUnmappedHttpError extends BasePineconeError {
  constructor(failedRequest: FailedRequestInfo) {
    const { url, status, body, message } = failedRequest;
    const intro = url
      ? `An unexpected error occured while calling the ${url} endpoint. `
      : '';
    const statusMsg = status ? `Status: ${status}. ` : '';
    const bodyMsg = body ? `Body: ${body}` : '';

    super([intro, message, statusMsg, bodyMsg].join(' ').trim());
    this.name = 'PineconeUnmappedHttpError';
  }
}

/** @internal */
export const mapHttpStatusError = (
  failedRequestInfo: FailedRequestInfo,
): BasePineconeError => {
  switch (failedRequestInfo.status) {
    case 400:
      return new PineconeBadRequestError(failedRequestInfo);
    case 401:
      return new PineconeAuthorizationError(failedRequestInfo);
    case 402:
      return new PineconePaymentRequiredError(failedRequestInfo);
    case 403:
      return new PineconeBadRequestError(failedRequestInfo);
    case 404:
      return new PineconeNotFoundError(failedRequestInfo);
    case 405:
      return new PineconeMethodNotAllowedError(failedRequestInfo);
    case 409:
      return new PineconeConflictError(failedRequestInfo);
    case 412:
      return new PineconeFailedPreconditionError(failedRequestInfo);
    case 422:
      return new PineconeUnprocessableEntityError(failedRequestInfo);
    case 500:
      return new PineconeInternalServerError(failedRequestInfo);
    case 501:
      return new PineconeNotImplementedError(failedRequestInfo);
    case 503:
      return new PineconeUnavailableError(failedRequestInfo);
    default:
      return new PineconeUnmappedHttpError(failedRequestInfo);
  }
};
